sys_script_include.script:
// Role: keeps the Mapping table in line with each control's "Targets" list (and, when asked, with the components
//       of those targets), with the CMDB owners, and moves stale evidence to Expired. Nobody edits Mapping rows by hand.
var CPMMapping = Class.create();
CPMMapping.prototype = {
  initialize: function() {
    this.util = new CPMUtil();
  },

  // Role: makes the mappings of one control match what the control asks for.
  //       New targets get a Missing mapping, removed targets are deactivated (history is kept),
  //       and every owner is brought in line with the CMDB.
  syncControl: function(control) {
    var wanted = this._wanted(control);
    var existing = this._existing(control);
    var controlId = control.getUniqueValue();

    for (var id in wanted) {
      var want = wanted[id];
      var have = existing[id];
      if (!have) this._create(controlId, id, want);
      else if (!have.active || have.owner !== want.owner || have.via !== want.via) this._update(have.id, true, want);
    }
    for (var other in existing) {
      if (!(other in wanted) && existing[other].active) this._update(existing[other].id, false, null);
    }
  },

  // Role: nightly. Copies the CMDB owner onto every active mapping, so a change of owner in the CMDB needs no action here.
  //       A component without owner takes the owner of the service it was included through.
  refreshOwners: function() {
    var mapping = new GlideRecord('x_1929776_compli_0_mapping');
    mapping.addQuery('active', true);
    mapping.query();
    while (mapping.next()) {
      var owner = (mapping.target.owned_by + '') || (mapping.target.managed_by + '') ||
                  (mapping.via_service.owned_by + '') || (mapping.via_service.managed_by + '') ||
                  this.util.prop('fallback_owner', '');
      if (owner !== (mapping.getValue('owner') || '')) {
        mapping.setValue('owner', owner);
        mapping.update();
      }
    }
  },

  // Role: nightly. Approved evidence whose date has passed becomes Expired.
  //       If the owner already sent a renewal, the mapping goes back to Awaiting review instead.
  expire: function() {
    var pending = {};
    var evidence = new GlideAggregate('x_1929776_compli_0_evidence');
    evidence.addQuery('status', 'pending');
    evidence.addAggregate('COUNT');
    evidence.groupBy('mapping');
    evidence.query();
    while (evidence.next()) pending[evidence.getValue('mapping')] = true;

    var mapping = new GlideRecord('x_1929776_compli_0_mapping');
    mapping.addQuery('state', 'approved');
    mapping.addQuery('valid_until', '<', this.util.today());
    mapping.query();
    while (mapping.next()) {
      mapping.setValue('state', pending[mapping.getUniqueValue()] ? 'awaiting' : 'expired');
      mapping.update();
    }
  },

  // Role: everything a control should apply to, as { ciId: { owner, via } }.
  //       "via" is empty for a target picked by the admin, and holds the service id for a component added automatically.
  _wanted: function(control) {
    var wanted = {};
    var list = control.getValue('active') == '1' ? (control.getValue('targets') || '') : '';
    var ids = list.split(',').filter(String);
    if (!ids.length) return wanted;

    var targetOwner = {};
    var ci = new GlideRecord('cmdb_ci');
    ci.addQuery('sys_id', 'IN', ids.join(','));
    ci.query();
    while (ci.next()) {
      targetOwner[ci.getUniqueValue()] = this.util.ownerOf(ci) || '';
      wanted[ci.getUniqueValue()] = { owner: targetOwner[ci.getUniqueValue()], via: '' };
    }
    if (control.getValue('include_components') == '1') this._addComponents(wanted, targetOwner);
    return wanted;
  },

  // Role: adds the components of every target (found through the CMDB relationships) to the wanted list.
  //       A CI that is already wanted keeps its first reason. A component without owner inherits the service owner.
  _addComponents: function(wanted, targetOwner) {
    var scope = new CPMScope();
    for (var targetId in targetOwner) {
      var ids = Object.keys(scope.componentsOf(targetId)).filter(function(id) { return !wanted[id]; });
      if (!ids.length) continue;
      var ci = new GlideRecord('cmdb_ci');
      ci.addQuery('sys_id', 'IN', ids.join(','));
      ci.query();
      while (ci.next()) {
        var id = ci.getUniqueValue();
        if (wanted[id]) continue;
        wanted[id] = { owner: ci.getValue('owned_by') || ci.getValue('managed_by') || targetOwner[targetId], via: targetId };
      }
    }
  },

  // Role: the mappings that already exist for a control, as { ciId: { id, active, owner, via } }.
  _existing: function(control) {
    var map = {};
    var mapping = new GlideRecord('x_1929776_compli_0_mapping');
    mapping.addQuery('control', control.getUniqueValue());
    mapping.query();
    while (mapping.next()) {
      map[mapping.getValue('target')] = {
        id: mapping.getUniqueValue(),
        active: mapping.getValue('active') == '1',
        owner: mapping.getValue('owner') || '',
        via: mapping.getValue('via_service') || ''
      };
    }
    return map;
  },

  // Role: creates a blank mapping. Its first state is Missing: the owner has to provide evidence.
  _create: function(controlId, targetId, want) {
    var mapping = new GlideRecord('x_1929776_compli_0_mapping');
    mapping.initialize();
    mapping.setValue('control', controlId);
    mapping.setValue('target', targetId);
    mapping.setValue('owner', want.owner);
    mapping.setValue('via_service', want.via);
    mapping.setValue('state', 'missing');
    mapping.setValue('active', true);
    mapping.insert();
  },

  // Role: switches a mapping on or off, and when "want" is given, refreshes its owner and its reason for being there.
  _update: function(mappingId, active, want) {
    var mapping = new GlideRecord('x_1929776_compli_0_mapping');
    if (!mapping.get(mappingId)) return;
    mapping.setValue('active', active);
    if (want) {
      mapping.setValue('owner', want.owner);
      mapping.setValue('via_service', want.via);
    }
    mapping.update();
  },

  type: 'CPMMapping'
};
